import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Bell, Search, Menu, User, Settings, LogOut, MessageSquare, Package, Users, AlertCircle, CheckCircle } from 'lucide-react';
import useNotifications from './';

const TopBar = ({ toggleSidebar, toggleDarkMode, darkMode }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const navigate = useNavigate();
  const location = useLocation();

  // Utiliser le hook notifications
  const {
    notifications,
    stats,
    loading,
    fetchNotifications,
    markAsRead,
    markAllAsRead,
    deleteNotification,
    formatTime,
    getNotificationIcon,
    getNotificationColor,
    getPriorityColor
  } = useNotifications();

  // Charger les notifications au démarrage
  useEffect(() => {
    fetchNotifications({ limit: 10, unreadOnly: false });
  }, [fetchNotifications]);

  // Fonction pour basculer le mode sombre
  const handleToggleDarkMode = () => {
    toggleDarkMode();
    localStorage.setItem('darkMode', !darkMode);
  };

  // Fonction pour marquer toutes les notifications comme lues
  const handleMarkAllAsRead = async () => {
    const success = await markAllAsRead();
    if (success) {
      setShowNotifications(false);
    }
  };

  // Fonction pour gérer la suppression
  const handleDeleteNotification = async (id, e) => {
    e.stopPropagation();
    await deleteNotification(id);
  };

  // Fonction pour gérer la recherche
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      console.log('Recherche:', searchQuery);
      // Implémentez votre logique de recherche ici
      // Par exemple, navigation vers une page de résultats
      navigate(`/admin/search?q=${encodeURIComponent(searchQuery)}`);
    }
  };

  // Fonction pour obtenir l'icône Lucide selon le type
  const getLucideIcon = (type) => {
    switch (type) {
      case 'message': return MessageSquare;
      case 'order': return Package;
      case 'user': return Users;
      case 'alert':
      case 'warning': return AlertCircle;
      case 'success': return CheckCircle;
      case 'system': return Settings;
      default: return Bell;
    }
  };

  // Fonction pour gérer le clic sur une notification
  const handleNotificationClick = async (notification) => {
    try {
      // Marquer comme lue si ce n'est pas déjà fait
      if (!notification.is_read) {
        await markAsRead(notification.id);
      }

      // Naviguer selon les données de la notification
      if (notification.data?.action) {
        navigate(notification.data.action);
      } else {
        // Navigation par défaut selon le type
        switch (notification.type) {
          case 'message':
            navigate('/admin/messages');
            break;
          case 'order':
            navigate('/admin/orders');
            break;
          case 'user':
            navigate('/admin/users');
            break;
          case 'system':
            navigate('/admin/system');
            break;
          default:
            navigate('/admin/notifications');
            break;
        }
      }

      setShowNotifications(false);
    } catch (error) {
      console.error('Erreur lors du clic sur la notification:', error);
    }
  };

  // Fonction pour déconnexion
  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userData');
    navigate('/login');
    setShowUserMenu(false);
  };

  const getPageTitle = () => {
    const path = location.pathname;

    const pageTitles = {
      '/admin': 'Tableau de bord',
      '/admin/dashboard': 'Tableau de bord',
      '/admin/users': 'Gestion des utilisateurs',
      '/admin/products': 'Gestion des produits',
      '/admin/orders': 'Commandes',
      '/admin/analytics': 'Analytique',
      '/admin/messages': 'Messages',
      '/admin/settings': 'Paramètres',
      '/admin/reports': 'Rapports',
      '/admin/calendar': 'Calendrier',
      '/admin/notifications': 'Notifications',
      '/admin/system': 'Système',
      '/admin/database': 'Base de données',
      '/admin/backup': 'Sauvegarde',
      '/admin/help': 'Aide & Support',
    };

    return pageTitles[path] || 'Tableau de bord';
  };

  const getBreadcrumbs = () => {
    const path = location.pathname;
    const segments = path.split('/').filter(segment => segment);

    if (segments.length === 0) return ['Tableau de bord'];

    const breadcrumbMap = {
      'admin': 'Tableau de bord',
      'dashboard': 'Tableau de bord',
      'users': 'Utilisateurs',
      'products': 'Produits',
      'orders': 'Commandes',
      'analytics': 'Analytique',
      'messages': 'Messages',
      'settings': 'Paramètres',
      'reports': 'Rapports',
      'calendar': 'Calendrier',
      'notifications': 'Notifications',
      'system': 'Système',
      'database': 'Base de données',
      'backup': 'Sauvegarde',
      'help': 'Aide & Support',
    };

    return segments.map(segment => breadcrumbMap[segment] || segment);
  };

  const pageTitle = getPageTitle();
  const breadcrumbs = getBreadcrumbs();
  const unreadCount = stats.unread || 0;

  return (
    <header className="sticky top-0 z-50 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-b border-neutral-200/50 dark:border-neutral-800/50 shadow-sm">
      <div className="px-6 py-3">
        <div className="flex items-center justify-between">
          {/* Left side */}
          <div className="flex items-center space-x-4">
            <button
              onClick={toggleSidebar}
              className="lg:hidden p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
              aria-label="Toggle sidebar"
            >
              <Menu className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
            </button>

            <div>
              <h1 className="text-lg font-bold text-neutral-900 dark:text-white">
                {pageTitle}
              </h1>
              <div className="flex items-center space-x-1 text-xs text-neutral-500 dark:text-neutral-400">
                {breadcrumbs.map((crumb, index) => (
                  <React.Fragment key={index}>
                    <span className="truncate max-w-[100px]">{crumb}</span>
                    {index < breadcrumbs.length - 1 && (
                      <span className="text-neutral-300 dark:text-neutral-600 mx-1">/</span>
                    )}
                  </React.Fragment>
                ))}
              </div>
            </div>
          </div>

          {/* Right side */}
          <div className="flex items-center space-x-2">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative hidden md:block">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-neutral-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Rechercher..."
                className="pl-9 pr-4 py-1.5 w-56 rounded-xl bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent text-sm text-neutral-900 dark:text-white placeholder-neutral-500"
              />
            </form>

            {/* Notifications */}
            <div className="relative">
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors group"
                aria-label="Notifications"
              >
                <Bell className="h-5 w-5 text-neutral-700 dark:text-neutral-300 group-hover:text-primary-500 transition-colors" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 h-4 w-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center animate-pulse">
                    {unreadCount > 9 ? '9+' : unreadCount}
                  </span>
                )}
              </button>

              {/* Dropdown Notifications */}
              {showNotifications && (
                <>
                  {/* Overlay pour fermer en cliquant à côté */}
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setShowNotifications(false)}
                  />

                  <div className="absolute right-0 mt-2 w-96 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50 max-h-[80vh] flex flex-col">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-700 flex-shrink-0">
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="font-semibold text-neutral-900 dark:text-white text-sm">
                          Notifications
                        </h3>
                        {unreadCount > 0 && (
                          <button
                            onClick={handleMarkAllAsRead}
                            className="text-xs text-primary-600 dark:text-primary-400 hover:underline font-medium"
                            disabled={loading}
                          >
                            {loading ? '...' : 'Tout marquer comme lu'}
                          </button>
                        )}
                      </div>

                      {/* Stats rapides */}
                      <div className="flex items-center gap-2 text-xs">
                        <span className="px-2 py-1 rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400">
                          💬 {stats.messages || 0}
                        </span>
                        <span className="px-2 py-1 rounded-full bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400">
                          👤 {stats.users || 0}
                        </span>
                        <span className="px-2 py-1 rounded-full bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400">
                          ⚙️ {stats.system || 0}
                        </span>
                        {stats.important > 0 && (
                          <span className="px-2 py-1 rounded-full bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400">
                            ⚠️ {stats.important || 0}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="flex-1 overflow-y-auto">
                      {loading ? (
                        <div className="p-8 text-center">
                          <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary-500 mx-auto mb-3"></div>
                          <p className="text-sm text-neutral-500 dark:text-neutral-400">
                            Chargement des notifications...
                          </p>
                        </div>
                      ) : notifications.length === 0 ? (
                        <div className="p-8 text-center">
                          <Bell className="h-10 w-10 text-neutral-400 mx-auto mb-3" />
                          <p className="text-sm text-neutral-500 dark:text-neutral-400">
                            Aucune notification
                          </p>
                          <p className="text-xs text-neutral-400 dark:text-neutral-500 mt-1">
                            Vous serez notifié des nouvelles activités
                          </p>
                        </div>
                      ) : (
                        <div className="divide-y divide-neutral-100 dark:divide-neutral-700">
                          {notifications.map(notification => {
                            const Icon = getLucideIcon(notification.type);

                            return (
                              <div
                                key={notification.id}
                                onClick={() => handleNotificationClick(notification)}
                                className={`p-4 cursor-pointer transition-all duration-200 hover:bg-neutral-50 dark:hover:bg-neutral-700/50 ${
                                  !notification.is_read ? 'bg-blue-50/30 dark:bg-blue-900/5' : ''
                                }`}
                              >
                                <div className="flex items-start gap-3">
                                  <div className={`h-9 w-9 rounded-full ${getNotificationColor(notification.type)} flex items-center justify-center flex-shrink-0`}>
                                    <Icon className="h-4 w-4" />
                                  </div>
                                  <div className="flex-1 min-w-0">
                                    <div className="flex items-start justify-between mb-1 gap-2">
                                      <h4 className={`font-medium text-sm truncate ${
                                        !notification.is_read 
                                          ? 'text-neutral-900 dark:text-white font-semibold' 
                                          : 'text-neutral-700 dark:text-neutral-300'
                                      }`}>
                                        {notification.title}
                                      </h4>
                                      {notification.priority === 'high' || notification.priority === 'critical' ? (
                                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${getPriorityColor(notification.priority)} flex-shrink-0`}>
                                          {notification.priority === 'critical' ? 'CRITIQUE' : 'ÉLEVÉE'}
                                        </span>
                                      ) : null}
                                    </div>
                                    <p className="text-xs text-neutral-600 dark:text-neutral-400 mb-2 line-clamp-2">
                                      {notification.message}
                                    </p>
                                    <div className="flex items-center justify-between">
                                      <div className="flex items-center gap-2">
                                        {notification.sender_name && (
                                          <span className="text-xs text-neutral-500 dark:text-neutral-500">
                                            De: {notification.sender_name}
                                          </span>
                                        )}
                                      </div>
                                      <div className="flex items-center gap-3">
                                        <span className="text-xs text-neutral-500">
                                          {formatTime(notification.created_at)}
                                        </span>
                                        <button
                                          onClick={(e) => handleDeleteNotification(notification.id, e)}
                                          className="text-xs text-neutral-400 hover:text-red-500 transition-colors p-1"
                                          title="Supprimer"
                                        >
                                          ×
                                        </button>
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>

                    <div className="p-3 border-t border-neutral-200 dark:border-neutral-700 flex-shrink-0">
                      <button
                        onClick={() => {
                          navigate('/admin/notifications');
                          setShowNotifications(false);
                        }}
                        className="w-full py-2 text-sm text-primary-600 dark:text-primary-400 hover:bg-neutral-50 dark:hover:bg-neutral-700 rounded-lg transition-colors font-medium"
                      >
                        Voir toutes les notifications ({stats.total || 0})
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* User Menu */}
            <div className="relative">
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center space-x-3 pl-3 border-l border-neutral-200 dark:border-neutral-800 hover:opacity-80 transition-opacity group"
              >
                <div className="h-8 w-8 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center shadow-lg group-hover:shadow-primary-500/20 transition-shadow">
                  <User className="h-4 w-4 text-white" />
                </div>
                <div className="hidden md:block text-left">
                  <p className="text-sm font-medium text-neutral-900 dark:text-white">
                    Admin
                  </p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400">
                    Administrateur
                  </p>
                </div>
              </button>

              {/* Dropdown User Menu */}
              {showUserMenu && (
                <>
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setShowUserMenu(false)}
                  />

                  <div className="absolute right-0 mt-2 w-56 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                      <p className="font-medium text-neutral-900 dark:text-white text-sm">
                        Administrateur
                      </p>
                      <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">
                        admin@nexus.com
                      </p>
                    </div>

                    <div className="p-2 space-y-1">
                      <button
                        onClick={() => {
                          navigate('/admin/profile');
                          setShowUserMenu(false);
                        }}
                        className="w-full px-3 py-2 text-sm text-left rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2 transition-colors"
                      >
                        <User className="h-4 w-4" />
                        Mon profil
                      </button>

                      <button
                        onClick={() => {
                          navigate('/admin/settings');
                          setShowUserMenu(false);
                        }}
                        className="w-full px-3 py-2 text-sm text-left rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2 transition-colors"
                      >
                        <Settings className="h-4 w-4" />
                        Paramètres
                      </button>

                      <div className="h-px bg-neutral-200 dark:bg-neutral-700 my-1" />

                      <button
                        onClick={handleLogout}
                        className="w-full px-3 py-2 text-sm text-left rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 flex items-center gap-2 transition-colors"
                      >
                        <LogOut className="h-4 w-4" />
                        Déconnexion
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

export default TopBar;
